# The release builder embeds the exact readable, separately supplied core here.
_EMBEDDED_CORE = ''

def _load_core():
    path = Path(__file__).resolve().with_name("DKT_Affect_Lite_v2_1.py")
    if not path.exists():
        if not _EMBEDDED_CORE:
            raise FileNotFoundError("Put the supplied DKT_Affect_Lite_v2_1.py beside this file.")
        raw = zlib.decompress(base64.b64decode(_EMBEDDED_CORE))
        if hashlib.sha256(raw).hexdigest() != CORE_SHA256:
            raise RuntimeError("Embedded core checksum mismatch.")
        vendor = Path(tempfile.gettempdir()) / ("dkt_temporal_core_" + CORE_SHA256[:16])
        vendor.mkdir(parents=True, exist_ok=True)
        path = vendor / "DKT_Affect_Lite_v2_1.py"
        if not path.exists():
            tmp = path.with_suffix(".tmp"); tmp.write_bytes(raw); os.replace(tmp, path)
    if hashlib.sha256(path.read_bytes()).hexdigest() != CORE_SHA256:
        raise RuntimeError("Core source differs from the audited v2.1. Do not substitute a namesake file.")
    name = "_dkt_temporal_pinned_core_v21"
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec); sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod

