@dataclass
class Config(core.Config):
    output_dir: str = "/content/drive/MyDrive/DRAKT/runs/dkt_temporal_affect_v3"
    local_dir: str = "/content/dkt_temporal_affect_v3_cache"
    profiles: tuple[str, ...] = DEFAULT_PROFILES
    short_window: int = 3
    long_window: int = 10
    # auto: import a completed compatible v2.1 encoder, otherwise train once here.
    encoder_source_root: str = "auto"
    bootstrap_replicates: int = 1000
    target_coverage: float = 0.10
    prefix_audit_students: int = 16
    run_tests: bool = True

    def validate(self):
        # The core validates all unchanged architecture/data/optimizer choices.
        base = core.Config(**{f.name: getattr(self, f.name) for f in fields(core.Config)})
        base.profiles = ("cognitive", "behavior", "affect", "shuffled_affect")
        base.validate()
        if not 1 <= self.short_window < self.long_window:
            raise ValueError("Require 1 <= short_window < long_window.")
        if not set(DEFAULT_PROFILES) <= set(self.profiles) or not set(self.profiles) <= set(PROFILES):
            raise ValueError("Keep all four research controls. Optional: affect_availability_only.")
        if len(set(self.profiles)) != len(self.profiles):
            raise ValueError("Duplicate profiles.")
        if "readiness" not in self.tasks:
            raise ValueError("Readiness is the prespecified primary endpoint; retain its head.")
        if self.bootstrap_replicates < 100 or self.prefix_audit_students < 1:
            raise ValueError("Require >=100 bootstrap replicates and a positive prefix audit size.")
        if not 0 < self.target_coverage < 1:
            raise ValueError("target_coverage must be strictly between zero and one.")


def layout_for(hidden: int) -> dict:
    """Channel-major summaries: values and a distinct validity mask for every value."""
    layout = {}; cursor = 0
    for name, width in (("state", hidden), ("context", 4),
        ("behavior", len(BEHAVIOR_CHANNELS)*len(STATS)),
        ("affect", len(AFFECT_NAMES)*len(STATS)),
        ("affect_mask", len(AFFECT_NAMES)*len(STATS)),
        ("behavior_mask", len(BEHAVIOR_CHANNELS)*len(STATS)), ("behavior_provenance", 5)):
        layout[name] = (cursor, cursor + width); cursor += width
    layout["dim"] = cursor
    return layout


def feature_names(hidden: int) -> list[str]:
    return ([f"DKT_state_{i}" for i in range(hidden)] +
        ["current_correct", "log1p_skill_exposures", "log1p_skill_gap_days", "log1p_skill_gap_steps"] +
        [f"behavior/{c}/{s}" for c in BEHAVIOR_CHANNELS for s in STATS] +
        [f"affect/{c}/{s}" for c in AFFECT_NAMES for s in STATS] +
        [f"affect_valid/{c}/{s}" for c in AFFECT_NAMES for s in STATS] +
        [f"behavior_valid/{c}/{s}" for c in BEHAVIOR_CHANNELS for s in STATS] +
        [f"behavior_provenance/{c}" for c in core.BEHAVIOR_NAMES])


def causal_summaries(values, observed, skills, short=3, long=10):
    """Pure prefix-only features. Window widths count interaction POSITIONS.

    Missing values do not count as zero observations. No population/student fit,
    future outcomes, full-sequence baseline, target masks or time sorting occur here.
    Prior-person means and previous-skill values EXCLUDE the current event.
    Current and rolling features include it at the post-response decision time.
    """
    v = np.asarray(values, dtype=np.float64); m = np.asarray(observed, dtype=bool)
    q = np.asarray(skills, dtype=np.int64)
    if v.ndim != 2 or v.shape != m.shape or len(q) != len(v) or not 1 <= short < long:
        raise ValueError("Invalid temporal feature shapes/windows.")
    if not np.isfinite(v[m]).all():
        raise ValueError("Observed feature values must be finite.")
    n, d = v.shape
    out = np.zeros((n, d, len(STATS)), np.float32)
    valid = np.zeros_like(out, dtype=bool)
    if not n: return out.reshape(n, d*len(STATS)), valid.reshape(n, d*len(STATS))
    safe = np.where(m, v, 0.)
    totals = np.vstack([np.zeros((1,d)), np.cumsum(safe, axis=0)])
    squares = np.vstack([np.zeros((1,d)), np.cumsum(safe*safe, axis=0)])
    counts = np.vstack([np.zeros((1,d)), np.cumsum(m, axis=0)])
    ends = np.arange(1, n+1); rows = np.arange(n)[:,None]; dims = np.arange(d)[None,:]
    def window(w):
        starts = np.maximum(0, ends-w)
        cnt = counts[ends]-counts[starts]
        sums = totals[ends]-totals[starts]
        sq = squares[ends]-squares[starts]
        mean = sums/np.maximum(cnt,1)
        var = np.maximum(sq/np.maximum(cnt,1)-mean*mean,0.)
        coverage = cnt/(ends-starts)[:,None]
        return mean,cnt,var,coverage
    ms,cs,_,covs = window(short); ml,cl,varl,covl = window(long)
    prior_count = counts[:-1]; prior_mean = totals[:-1]/np.maximum(prior_count,1)
    available_pos = np.maximum.accumulate(np.where(m, rows, -1), axis=0)
    prev = np.vstack([np.full((1,d),-1), available_pos[:-1]])
    prev_value = safe[np.maximum(prev,0), dims]
    same_prev = np.full((n,d),-1, dtype=np.int64)
    for skill in np.unique(q):
        loc = np.flatnonzero(q==skill)
        prior = np.maximum.accumulate(np.where(m[loc],loc[:,None],-1),axis=0)
        if len(loc)>1: same_prev[loc[1:]] = prior[:-1]
    same_value = safe[np.maximum(same_prev,0), dims]
    def put(name, x, mask):
        j = STATS.index(name); valid[:,:,j] = np.broadcast_to(mask,(n,d))
        out[:,:,j] = np.where(valid[:,:,j],x,0.)
    put("current",safe,m)
    put("delta_previous",safe-prev_value,m & (prev>=0))
    put("mean_short",ms,cs>0); put("mean_long",ml,cl>0)
    put("short_minus_long",ms-ml,(cs>0)&(cl>0))
    put("std_long",np.sqrt(varl),cl>=2)
    put("prior_student_mean",prior_mean,prior_count>0)
    put("current_minus_prior_mean",safe-prior_mean,m&(prior_count>0))
    put("previous_same_skill",same_value,same_prev>=0)
    put("delta_same_skill",safe-same_value,m&(same_prev>=0))
    put("log1p_prior_count",np.log1p(prior_count),True)
    put("coverage_short",covs,True); put("coverage_long",covl,True)
    put("log1p_gap_previous",np.log1p(np.maximum(rows-prev,0)),prev>=0)
    put("log1p_gap_same_skill",np.log1p(np.maximum(rows-same_prev,0)),same_prev>=0)
    return out.reshape(n,-1),valid.reshape(n,-1)



def lagged_affect_summaries(values,observed,skills,short=3,long=10):
    """Use only affect through t-1, while querying SAME-SKILL history for q_t.

    Global summaries are shifted once. Same-skill scores keep their ORIGINAL
    skill association: do not shift scores onto the next event's different skill.
    delta_same_skill uses the two most recent available q_t scores before t.
    """
    q=np.asarray(skills,np.int64); v=np.asarray(values,np.float64); m=np.asarray(observed,bool)
    full,full_mask=causal_summaries(v,m,q,short,long)
    out=np.zeros_like(full); valid=np.zeros_like(full_mask)
    if len(q)>1: out[1:]=full[:-1]; valid[1:]=full_mask[:-1]
    n,d=v.shape; safe=np.where(m,v,0.)
    for skill in np.unique(q):
        loc=np.flatnonzero(q==skill)
        for ch in range(d):
            events=loc[m[loc,ch]]
            cursor=np.searchsorted(events,loc,side="left")-1
            has=cursor>=0; has2=cursor>=1
            last=np.zeros(len(loc)); delta=np.zeros(len(loc)); gap=np.zeros(len(loc))
            if len(events):
                indices=events[np.maximum(cursor,0)]
                last=safe[indices,ch]
                delta=last-safe[events[np.maximum(cursor-1,0)],ch]
                gap=np.log1p(np.maximum(loc-indices,0))
            for name,val,mask in (("previous_same_skill",last,has),("delta_same_skill",delta,has2),("log1p_gap_same_skill",gap,has)):
                col=ch*len(STATS)+STATS.index(name)
                out[loc,col]=np.where(mask,val,0.); valid[loc,col]=mask
    return out,valid

def context_features(seq, cfg):
    """Make histories for BEHAVIOR AND AFFECT using identical operators/windows."""
    q = core.to_np(seq["skill_ids"],np.int64)
    answer = core.to_np(seq["answers"],np.float32)
    b = core.to_np(seq["behavior_features"],np.float32)
    if "behavior_mask" in seq:
        bm = core.to_np(seq["behavior_mask"],bool); provenance = bm.astype(np.float32)
    else:
        bm = np.isfinite(b); provenance = np.full_like(b,-1,dtype=np.float32)
    behavior = np.column_stack((answer,b)); bmask = np.column_stack((np.ones(len(q),bool),bm))
    a = core.to_np(seq["affect_values"],np.float32).copy()
    am = core.to_np(seq["affect_mask"],bool).copy()
    bh,bhm = causal_summaries(behavior,bmask,q,cfg.short_window,cfg.long_window)
    if cfg.affect_timing == "lagged":
        ah,ahm = lagged_affect_summaries(a,am,q,cfg.short_window,cfg.long_window)
    else:
        ah,ahm = causal_summaries(a,am,q,cfg.short_window,cfg.long_window)
    return {"context": core.causal_context(seq), "behavior":bh, "behavior_mask":bhm,
            "affect":ah, "affect_mask":ahm, "behavior_provenance":provenance}


def audit_prefixes(data, cfg):
    """Compare full-history feature prefixes with independently recomputed prefixes."""
    choice=np.linspace(0,len(data.sequences)-1,min(cfg.prefix_audit_students,len(data.sequences)),dtype=int)
    checked=0
    for i in choice:
        seq=data.sequences[int(i)]; n=int(seq["length"]); full=context_features(seq,cfg)
        for cut in sorted(set((1,max(1,n//2),n))):
            prefix={}
            for k,v in seq.items():
                try: is_event = not isinstance(v,(str,dict)) and len(v)==n
                except TypeError: is_event=False
                prefix[k]=v[:cut] if is_event else v
            prefix["length"]=cut
            part=context_features(prefix,cfg)
            for k in full: np.testing.assert_allclose(full[k][:cut],part[k],rtol=0,atol=1e-6)
            checked+=1
    return {"students_checked":len(choice),"prefixes_checked":checked,"passed":True,
        "rule":"All engineered inputs computed from the available prefix only; no labels are read.",
        "limitation":"Does not audit temporal provenance of the upstream affect detector."}


