def fixed_capacity_policy(y,p,coverage,min_selected=100):
    """An offline ranking-capacity policy, selected from scores, NEVER outcomes.

    This is NOT a fixed online probability threshold or a prospective learning
    intervention. At test time the predetermined quota may use test SCORES only.
    Ties remain intact and the capacity is never exceeded.
    """
    y=np.asarray(y); p=np.asarray(p)
    budget=int(math.floor(len(p)*coverage))
    if not len(p) or budget<min_selected:
        return {"available":False,"reason":"too few eligible predictions for quota/minimum support","selected":0,"coverage":0.}
    order=np.argsort(-p,kind="stable"); sorted_p=p[order]
    ends=np.r_[np.flatnonzero(sorted_p[:-1]!=sorted_p[1:]),len(p)-1]
    allowable=ends[(ends+1<=budget)&(ends+1>=min_selected)]
    if not len(allowable):
        return {"available":False,"reason":"score ties prevent supported selection below quota","selected":0,"coverage":0.}
    n=int(allowable[-1]+1); threshold=float(sorted_p[n-1]); selected=p>=threshold
    return {"available":True,"threshold":threshold,"selected":n,"eligible":len(p),"coverage":n/len(p),
        "requested_coverage":coverage,"precision":float(y[selected].mean()),
        "false_ready_fraction_among_selected":float(1-y[selected].mean()),
        "selection_uses_labels":False,"interpretation":"offline batch ranking at fixed capacity, not an online threshold or guaranteed risk"}


def export_readouts(model,store,prob,metrics,cfg,out,signature,seed,data,dataset_id,best_epochs,split_name,policies=None):
    rows=core.export_readouts(model,store,prob,metrics,cfg,out,signature,seed,data,dataset_id,best_epochs,split_name,policies)
    policy_rows=[]; j=list(cfg.tasks).index("readiness"); mask=np.asarray(store.arr["mask"][:,j],bool)
    for profile in cfg.profiles:
        m=model.members.index(("readiness",profile)); result_path=out/profile/f"{split_name}_result.json"
        report=json.loads(result_path.read_text())
        quota=fixed_capacity_policy(store.arr["y"][mask,j],prob[m,mask],cfg.target_coverage,cfg.policy_min_selected)
        report["fixed_capacity_readiness"]=quota
        report["affect_feature_condition"]=profile
        report["temporal_windows"]=[cfg.short_window,cfg.long_window]
        report["scope"]="validation_development_after_checkpoint_selection" if split_name=="validation" else "locked_test_evaluation"
        if profile=="disrupted_affect": report["donor_provenance"]=store.donor_audit
        save_json(report,result_path)
        policy_rows.append({"seed":seed,"profile":profile,"split":split_name,**quota})
    pd.DataFrame(policy_rows).to_csv(out/f"{split_name}_fixed_capacity_policy.csv",index=False)
    save_json(store.donor_audit,out/f"{split_name}_donor_audit.json")
    return rows


@torch.no_grad()
def audit_affect_integration(model,store,cfg,out,seed,signature,encoder_sha):
    """Fixed-model, validation-only sensitivity; not a selection objective."""
    n=min(cfg.affect_diagnostic_rows,store.N)
    if n==0: return {"skipped":True}
    rng=np.random.default_rng(cfg.split_seed+735291)
    rows=np.sort(rng.choice(store.N,n,replace=False))
    av=slice(*model.layout["affect"]); am=slice(*model.layout["affect_mask"])
    curr=np.array([i*len(STATS) for i in range(len(AFFECT_NAMES))])
    history=np.setdiff1d(np.arange(av.stop-av.start),curr)
    views=["aligned","history_at_training_mean","all_values_at_training_mean","all_affect_missing","coherent_donor_block"]
    views += ["neutralize_"+name for name in AFFECT_NAMES]
    members=[m for m,(t,p) in enumerate(model.members) if p!="disrupted_affect"]
    outputs={}
    for view in views:
        pieces=[]
        for start in range(0,n,min(cfg.readout_batch,1024)):
            b=store.get(rows[start:start+min(cfg.readout_batch,1024)]); b["x"]=b["x"].clone()
            if view=="history_at_training_mean": b["x"][:,av.start+history]=0.
            elif view=="all_values_at_training_mean": b["x"][:,av]=0.
            elif view=="all_affect_missing": b["x"][:,av]=0.; b["x"][:,am]=0.
            elif view=="coherent_donor_block": b["x"][:,av]=b["donor_affect"]; b["x"][:,am]=b["donor_mask"]
            elif view.startswith("neutralize_"):
                idx=list(AFFECT_NAMES).index(view[len("neutralize_"):])
                b["x"][:,av.start+idx*len(STATS):av.start+(idx+1)*len(STATS)]=0.
            pieces.append(model(b,members).sigmoid().cpu().numpy())
        outputs[view]=np.concatenate(pieces,axis=1)
    y=np.asarray(store.arr["y"])[rows]; masks=np.asarray(store.arr["mask"])[rows]; records=[]
    for mi,m in enumerate(members):
        task,p=model.members[m]; j=list(cfg.tasks).index(task); mask=masks[:,j]
        baseline=outputs["aligned"][mi]
        for view,pred in outputs.items():
            candidate=pred[mi]
            if p=="temporal_behavior" and not np.array_equal(candidate,baseline):
                raise AssertionError("Affect-only perturbation changed the temporal behavior control.")
            if p=="snapshot_affect" and view=="history_at_training_mean" and not np.array_equal(candidate,baseline):
                raise AssertionError("Snapshot head consumed excluded affect history.")
            metric=core.binary_metrics(y[mask,j],candidate[mask]); ref=core.binary_metrics(y[mask,j],baseline[mask])
            records.append({"seed":seed,"task":task,"profile":p,"view":view,"targets":int(mask.sum()),
                "mean_abs_probability_change":float(np.abs(candidate-baseline).mean()),
                "max_abs_probability_change":float(np.abs(candidate-baseline).max()),
                "brier":metric.get("brier"),"brier_increase_vs_aligned":metric.get("brier",0)-ref.get("brier",0) if mask.any() else None,
                "scope":"fixed_validation_sample; possibly out-of-distribution sensitivity, NOT causal effect"})
    out=Path(out); pd.DataFrame(records).to_csv(out/"temporal_affect_sensitivity.csv",index=False)
    raw=np.asarray(store.arr["x"])[rows]; layout=model.layout
    report={"signature":signature,"encoder_sha256":encoder_sha,"sample_rows":n,
        "sample_sha256":hashlib.sha256(rows.tobytes()).hexdigest(),"no_outcomes_used_to_select_sample":True,
        "temporal_behavior_invariant":True,"snapshot_ignores_history":True,"donor":store.donor_audit,
        "affect_columns":[],"warnings":["Sensitivity is not predictive benefit.","Mean replacement can be out of distribution.",
            "Missing affect in an affect-trained head need not equal the separately trained behavior head.",
            "Columns describing data availability may contain useful collection artifacts rather than affect."]}
    for c,name in enumerate(AFFECT_NAMES):
        for j,stat in enumerate(STATS):
            i=c*len(STATS)+j; observed=raw[:,am.start+i]>0; val=raw[observed,av.start+i]
            report["affect_columns"].append({"name":f"{name}/{stat}","sample_available":int(observed.sum()),
                "sample_mean":float(val.mean()) if len(val) else None,"sample_std":float(val.std()) if len(val) else None,
                "train_valid_count":store.normalizer_counts[av.start+i]})
    save_json(report,out/"temporal_affect_integration_audit.json")
    return report


# Training loop preserved from v2.1; dependencies above supply temporal heads.
def train_readouts(train_store,val_store,cfg,device,seed,out,signature,normalizer,data,dataset_id,encoder_sha):
    out.mkdir(parents=True,exist_ok=True); resultp=out/"result.json"; lastp=out/"last.pt"
    seed_all(seed+10000)
    rates=task_rates(train_store)
    for j,t in enumerate(cfg.tasks):
        if not np.asarray(val_store.arr["mask"][:,j],bool).any():
            raise ValueError(f"No validation labels for {t}; cannot select its checkpoint.")
    model=ReadoutBank(data.K,train_store.arr["x"].shape[1],cfg,rates).to(device)
    opt=IndependentAdam(model.parameters(),lr=cfg.readout_lr)
    M=len(model.members)
    state={"epoch":0,"best":[float("inf")]*M,"bad":[0]*M,"active":[True]*M,
           "best_epoch":[0]*M,"best_state":[None]*M,"history":[]}
    if resultp.exists():
        r=json.loads(resultp.read_text())
        if r["signature"]!=signature: raise RuntimeError("Readout result signature mismatch.")
        if not cfg.resume: raise RuntimeError("Completed readouts exist; use a new output directory.")
        for m,(t,p) in enumerate(model.members): model.load_member(m,checked_checkpoint(out/p/f"best_{t}.pt",signature,encoder_sha)["model"])
        return model,r
    if cfg.evaluate_test: raise RuntimeError("Finish readout training before final evaluation.")
    if lastp.exists():
        if not cfg.resume: raise RuntimeError("Readout checkpoint exists but resume=False.")
        ck=torch_load(lastp)
        if ck["signature"]!=signature: raise RuntimeError("Readout checkpoint signature mismatch.")
        model.load_state_dict(ck["model"]); opt.load_state_dict(ck["optimizer"]); optimizer_device(opt,device)
        state=ck["training"]; restore_rng(ck["rng"])
        print(f"Resuming independent readouts at epoch {state['epoch']+1}")
    task_ix=torch.tensor(model.task_indices,device=device)
    for epoch in range(state["epoch"]+1,cfg.readout_epochs+1):
        active=np.flatnonzero(state["active"])
        if not len(active): break
        model.train(); t0=time.perf_counter(); order=np.random.default_rng(seed+20000+epoch).permutation(train_store.N)
        nums=torch.zeros(M,device=device); dens=torch.zeros(M,device=device)
        for start in range(0,train_store.N,cfg.readout_batch):
            rows=order[start:start+cfg.readout_batch]; b=train_store.get(rows)
            logits=model(b,active); target=b["y"][:,task_ix[active]].T
            mask=b["mask"][:,task_ix[active]].T
            losses=F.binary_cross_entropy_with_logits(logits.float(),target,reduction="none")
            sum_=(losses*mask).sum(1); count=mask.sum(1)
            opt.zero_grad(set_to_none=True)
            (sum_/count.clamp_min(1)).sum().backward()
            clip_members(model)
            valid_members=active[count.detach().cpu().numpy()>0]
            opt.step(members=valid_members)
            nums[active]+=sum_.detach(); dens[active]+=count
        if device.type=="cuda": torch.cuda.synchronize(device)
        sec=time.perf_counter()-t0
        metrics,_=eval_readouts(model,val_store,cfg)
        for m in active:
            score=metrics[m].get("brier")
            if score is None: raise ValueError(f"No validation labels for {model.members[m]}")
            if score<state["best"][m]-cfg.epoch_min_delta:
                state["best"][m]=score; state["best_epoch"][m]=epoch; state["bad"][m]=0
                state["best_state"][m]=model.member_state(m)
                t,p=model.members[m]
                torch_save({"model":state["best_state"][m],"signature":signature,"epoch":epoch,"task":t,"profile":p,
                            "validation":metrics[m],"normalizer":normalizer,"layout":model.layout,
                            "selection":"validation_Brier","encoder_sha256":encoder_sha,
                            "input_feature_mask":model.feature_masks[m].cpu()},out/p/f"best_{t}.pt")
            else: state["bad"][m]+=1
            if state["bad"][m]>=cfg.readout_patience: state["active"][m]=False
        state["epoch"]=epoch
        train_losses=(nums/dens.clamp_min(1)).cpu().tolist()
        state["history"].append({"epoch":epoch,"train_seconds":sec,
            "members":[{"task":t,"profile":p,"active":state["active"][m],"train_bce":train_losses[m],
                        "validation":metrics[m],"best_epoch":state["best_epoch"][m]} for m,(t,p) in enumerate(model.members)]})
        torch_save({"model":cpu_state(model),"optimizer":opt.state_dict(),"training":state,
                    "signature":signature,"rng":rng_state()},lastp)
        save_json(state["history"],out/"epoch_history.json")
        ready=[(p,metrics[m]) for m,(t,p) in enumerate(model.members) if t=="readiness"]
        desc=" | ".join(f"{p}: Brier={v['brier']:.5f} AUC={float(v['auc']) if v.get('auc') is not None else float('nan'):.4f}" for p,v in ready)
        print(f"Readouts seed={seed} epoch={epoch:02d}/{cfg.readout_epochs} active={sum(state['active'])}/{M} train={sec:.1f}s | {desc}",flush=True)
    for m,s in enumerate(state["best_state"]):
        if s is None: raise RuntimeError(f"Head {model.members[m]} never trained.")
        model.load_member(m,s)
    metrics,prob=eval_readouts(model,val_store,cfg)
    rows=export_readouts(model,val_store,prob,metrics,cfg,out,signature,seed,data,dataset_id,state["best_epoch"],"validation")
    result={"signature":signature,"seed":seed,"rows":rows,"best_epochs":state["best_epoch"],
            "readout_parameters_total":sum(p.numel() for p in model.parameters()),
            "selection":"separate_validation_Brier_per_independent_target_head",
            "test_evaluation_deferred":True,"epochs_completed":state["epoch"]}
    save_json(simple_baselines(train_store,val_store,cfg),out/"simple_baselines_validation.json")
    if cfg.affect_diagnostic_rows:
        audit_affect_integration(model,val_store,cfg,out,seed,signature,encoder_sha)
    save_json(result,resultp)
    return model,result


def validate_import_source(root,data,split,cfg,seed,dataset_id):
    """Validate identities/settings/weights, not merely matching tensor shapes."""
    root=Path(root); manifest_path=root/"experiment_lock.json"
    if not manifest_path.exists(): raise RuntimeError("Encoder import: missing source experiment lock.")
    lock=json.loads(manifest_path.read_text()); scientific=lock["scientific_config"]
    if lock.get("source_code_sha256")!=CORE_SHA256:
        raise RuntimeError("Encoder import requires the exact audited v2.1 source hash.")
    if lock.get("dataset_sha256")!=dataset_id: raise RuntimeError("Encoder import dataset mismatch.")
    folder=root/f"fold_{cfg.fold:02d}"; ids=json.loads((folder/"split_indices.json").read_text())
    if ids!=split: raise RuntimeError("Encoder import student-split mismatch.")
    student_manifest=json.loads((folder/"split_identity_manifest.json").read_text())
    expected=[core.student_key(s["student_id"],dataset_id) for s in data.sequences]
    if student_manifest.get("student_keys_in_dataset_order")!=expected:
        raise RuntimeError("Encoder import ordered student identities mismatch.")
    for key in COGNITIVE_KEYS:
        if scientific.get(key)!=getattr(cfg,key):
            raise RuntimeError(f"Encoder import cognitive setting differs: {key}. Use matching settings or explicitly disable import.")
    source_copy=root/"source/DKT_Affect_Lite.py"
    if not source_copy.exists() or file_sha(source_copy)!=CORE_SHA256:
        raise RuntimeError("Encoder import: executed source snapshot missing or hash mismatch.")
    stage=folder/f"seed_{seed}"/"dkt"; result=json.loads((stage/"result.json").read_text())
    sig=digest_obj({"root":lock["signature"],"seed":seed})
    if result["signature"]!=sig: raise RuntimeError("Encoder result signature mismatch.")
    ck=core.checked_checkpoint(stage/"best.pt",sig)
    if ck["epoch"]!=result["best_epoch"]: raise RuntimeError("Encoder checkpoint epoch mismatch.")
    return ck,result,stage


def obtain_encoder(data,split,cfg,device,seed,out,signature,dataset_id):
    out=Path(out)
    if (out/"result.json").exists() or (out/"last.pt").exists():
        return core.train_dkt(data,split,cfg,device,seed,out,signature,dataset_id)
    if cfg.evaluate_test: raise RuntimeError("No compatible completed cognitive stage for final evaluation.")
    source=cfg.encoder_source_root
    if source=="auto": source=str(Path(cfg.project_dir)/"runs/dkt_affect_lite_v2_1_audited")
    candidate=Path(source)/f"fold_{cfg.fold:02d}/seed_{seed}/dkt/result.json" if source else None
    if candidate is not None and candidate.exists():
        ck,result,stage=validate_import_source(source,data,split,cfg,seed,dataset_id)
        model=core.FastDKT(data.K,cfg.hidden_dim,cfg.packed_lstm,cfg.interaction_encoding,cfg.dkt_initialization,cfg.dkt_output_dropout).to(device)
        model.load_state_dict(ck["model"]); model.eval()
        out.mkdir(parents=True,exist_ok=True)
        origin={"source_root":source,"source_checkpoint_sha256":file_sha(stage/"best.pt"),
            "source_signature":result["signature"],"source_code_sha256":CORE_SHA256,
            "student_identity_and_settings_verified":True,"weights_unchanged":True}
        core.torch_save({**ck,"signature":signature,"imported_encoder":origin},out/"best.pt")
        validation=core.eval_dkt(model,data,split["validation_indices"],cfg,device,out/"validation_predictions.npz",dataset_id)
        new_result={**result,"signature":signature,"validation":validation,"imported_encoder":origin}
        save_json(new_result,out/"result.json"); save_json(origin,out/"encoder_import.json")
        if (stage/"epoch_history.json").exists(): shutil.copyfile(stage/"epoch_history.json",out/"source_epoch_history.json")
        print(f"Imported completed v2.1 DKT seed {seed}; no recurrent retraining; all identities/settings verified.",flush=True)
        return model,new_result
    if source and cfg.encoder_source_root!="auto":
        raise FileNotFoundError(f"No completed encoder at {candidate}. Finish it or set encoder_source_root='' to train separately.")
    print(f"No completed v2.1 encoder for seed {seed}; training ONE cognitive model in the new directory.",flush=True)
    return core.train_dkt(data,split,cfg,device,seed,out,signature,dataset_id)


def paired_bootstrap(y,baseline,candidate,students,reps,seed):
    y=np.asarray(y); diff=(np.asarray(baseline)-y)**2-(np.asarray(candidate)-y)**2
    _,inv=np.unique(students,return_inverse=True); sums=np.bincount(inv,weights=diff); count=np.bincount(inv); G=len(count)
    if G<2: return {"available":False,"reason":"fewer than two students with labels"}
    rng=np.random.default_rng(seed); micro=[]; macro=[]; per_student=sums/count
    for start in range(0,reps,100):
        pick=rng.integers(0,G,size=(min(100,reps-start),G))
        micro.extend((sums[pick].sum(1)/count[pick].sum(1)).tolist()); macro.extend(per_student[pick].mean(1).tolist())
    lo,hi=np.quantile(micro,[.025,.975]); mlo,mhi=np.quantile(macro,[.025,.975])
    return {"available":True,"brier_improvement":float(diff.mean()),"ci_low":float(lo),"ci_high":float(hi),
        "student_macro_brier_improvement":float(per_student.mean()),"macro_ci_low":float(mlo),"macro_ci_high":float(mhi),
        "students_with_labels":G,"replicates":reps,
        "scope":"student-cluster sampling conditional on fitted models; no seed uncertainty or correction for validation selection"}


def comparative_reports(root,cfg,split_name="validation"):
    root=Path(root); rows=[]; effects=[]; intervals=[]; policies=[]
    contrasts=(("RQ1_primary","temporal_behavior","temporal_affect"),
               ("RQ2_temporal_vs_snapshot","snapshot_affect","temporal_affect"),
               ("negative_control","disrupted_affect","temporal_affect"))
    for seed in cfg.seeds:
        folder=root/f"fold_{cfg.fold:02d}/seed_{seed}"; stage=folder/"readouts"
        if not (stage/"result.json").exists(): continue
        if any(not (stage/p/f"{split_name}_result.json").exists() for p in cfg.profiles): continue
        by={}
        for p in cfg.profiles:
            report=json.loads((stage/p/f"{split_name}_result.json").read_text())
            policies.append({"seed":seed,"profile":p,"split":split_name,**report["fixed_capacity_readiness"]})
            for task in cfg.tasks:
                metric=report["binary"][task]; by[(p,task)]=metric
                rows.append({"seed":seed,"profile":p,"task":task,"split":split_name,
                    "best_epoch":report["task_checkpoints"][task],**metric})
        for contrast,base,cand in contrasts:
            with np.load(stage/base/f"{split_name}_predictions.npz",allow_pickle=False) as b, np.load(stage/cand/f"{split_name}_predictions.npz",allow_pickle=False) as a:
                for key in ("student_key","event_key","event_position","skill_id","exercise_id","task_names","label","mask","signature","dataset_sha256"):
                    if not np.array_equal(b[key],a[key]): raise RuntimeError(f"Paired export alignment mismatch: {key}")
                for j,t in enumerate(cfg.tasks):
                    rec={"seed":seed,"task":t,"contrast":contrast,"baseline":base,"candidate":cand,"split":split_name}
                    for metric in ("auc","average_precision","brier","bce","ece"):
                        bm=by[(base,t)].get(metric); am=by[(cand,t)].get(metric)
                        rec[metric+"_improvement"]=(am-bm)*(1 if metric in ("auc","average_precision") else -1) if bm is not None and am is not None else None
                    effects.append(rec)
                    m=b["mask"][:,j]
                    if m.any():
                        intervals.append({**{k:rec[k] for k in ("seed","task","contrast","baseline","candidate","split")},
                            **paired_bootstrap(b["label"][m,j],b["probability"][m,j],a["probability"][m,j],b["student_key"][m],cfg.bootstrap_replicates,917+seed+j),
                            "primary":t=="readiness" and contrast=="RQ1_primary"})
    if rows:
        frame=pd.DataFrame(rows); frame.to_csv(root/f"{split_name}_comparison.csv",index=False)
        pd.DataFrame(effects).to_csv(root/f"{split_name}_research_contrasts.csv",index=False)
        pd.DataFrame(intervals).to_csv(root/f"{split_name}_paired_brier_intervals.csv",index=False)
        pd.DataFrame(policies).to_csv(root/f"{split_name}_fixed_capacity_policy.csv",index=False)
        summary=frame.groupby(["profile","task"])[["auc","average_precision","brier","ece"]].agg(["mean","std","count"])
        summary.columns=["_".join(v) for v in summary.columns]; summary.to_csv(root/f"{split_name}_seed_summary.csv")
        print("\nREADINESS — "+split_name.upper()+" (not a claim of affect benefit):",flush=True)
        print(frame.loc[frame.task=="readiness",["seed","profile","brier","auc","average_precision","best_epoch"]].to_string(index=False),flush=True)
    return rows


def make_signature(cfg,dataset_id,split):
    science=asdict(cfg)
    for key in ("seeds","project_dir","output_dir","local_dir","prepared_cache","csv_path","split_path", "encoder_source_root",
        "resume","run_tests","evaluate_test","acknowledge_test_exposure","accept_assistments_terms","trust_own_cache","allow_download","keep_local_states"):
        science.pop(key,None)
    signature=digest_obj({"version":VERSION,"core_sha256":CORE_SHA256,"code":file_sha(__file__),
        "config":science,"dataset":dataset_id,"split":split})
    return signature,science



def temporal_cuda_smoke(cfg,device):
    """Executed in Colab, not claimed as a GPU test performed in this audit."""
    if device.type!="cuda": return
    core.seed_all(73392)
    model=ReadoutBank(4,layout_for(cfg.hidden_dim)["dim"],cfg,[.5]*len(cfg.tasks)).to(device)
    n=32; x=np.random.default_rng(911).normal(size=(n,layout_for(cfg.hidden_dim)["dim"])).astype(np.float32)
    for key in ("behavior_mask","affect_mask"): x[:,slice(*model.layout[key])]=1
    y=np.tile(np.arange(n)%2,(len(cfg.tasks),1)).T.astype(np.float32)
    with tempfile.TemporaryDirectory(prefix="dkt_temporal_cuda_") as td:
        bank=_write_test_bank(td,x,y,tasks=cfg.tasks)
        norm=fit_normalizer(bank,model.layout)
        resident=BankStore(bank,norm,device,1.,42)
        streamed=BankStore(bank,norm,device,0.,42)
        rb=resident.get(np.arange(n)); sb=streamed.get(np.arange(n))
        for key in rb: torch.testing.assert_close(rb[key],sb[key])
        opt=IndependentAdam(model.parameters(),lr=cfg.readout_lr)
        logits=model(rb); target=rb["y"][:,model.task_indices].T
        loss=F.binary_cross_entropy_with_logits(logits.float(),target)
        loss.backward(); core.clip_members(model); opt.step()
        if not torch.isfinite(loss) or not all(torch.isfinite(p).all() for p in model.parameters()):
            raise FloatingPointError("Temporal CUDA forward/backward/optimizer sanity check failed.")
        del resident,streamed
    del model,logits,loss,opt,rb,sb,target
    gc.collect(); torch.cuda.empty_cache()
    print("[PASS] Installed CUDA temporal heads, IndependentAdam and resident/streamed feature parity (synthetic only).",flush=True)

def run_experiment(cfg):
    cfg.validate()
    print(f"DKT + Temporal Affect {VERSION}; unchanged cognitive core {core.VERSION}",flush=True)
    if cfg.run_tests: run_self_tests()
    if cfg.project_dir.startswith("/content/drive/") and not Path("/content/drive/MyDrive").exists():
        raise RuntimeError("Mount Drive in an interactive Colab cell. This child process does not mount Drive.")
    device,environment=core.setup_device(cfg); core.cuda_runtime_smoke(cfg,device)
    temporal_cuda_smoke(cfg,device)
    environment["temporal_runner_version"]=VERSION
    environment["cognitive_core_sha256"]=CORE_SHA256
    out=Path(cfg.output_dir); out.mkdir(parents=True,exist_ok=True)
    payload,dataset_id,origin,preflight=core.prepare_data(cfg)
    split=core.get_split(payload,cfg); data=core.SequenceData(payload)
    signature,science=make_signature(cfg,dataset_id,split)
    lock=out/"experiment_lock.json"
    if lock.exists():
        if json.loads(lock.read_text()).get("signature")!=signature:
            raise RuntimeError("Existing temporal output has incompatible data/code/settings. Choose a NEW directory.")
    else:
        if cfg.evaluate_test: raise RuntimeError("No completed locked experiment for final evaluation.")
        save_json({"signature":signature,"scientific_config":science,"core_sha256":CORE_SHA256,
            "source_code_sha256":file_sha(__file__),"dataset_sha256":dataset_id,"source":origin,
            "research_protocol":make_research_protocol(cfg)},lock)
    # Header/audit operations may inspect structural identities but do not evaluate test outcomes.
    save_json(make_research_protocol(cfg),out/"research_protocol.json")
    save_json(core.source_fidelity_report(cfg),out/"cognitive_source_fidelity.json")
    preflight["temporal_prefix_audit"]=audit_prefixes(data,cfg)
    preflight["legacy_unknown_behavior_students"]=sum("behavior_mask" not in s for s in data.sequences)
    save_json(preflight,out/"data_preflight.json"); save_json(payload["audit"],out/"dataset_audit.json")
    save_json(environment,out/"environment.json"); save_json(asdict(cfg),out/"last_invocation.json")
    save_json({"layout":layout_for(cfg.hidden_dim),"names":feature_names(cfg.hidden_dim),
        "operators":STATS,"windows":[cfg.short_window,cfg.long_window],"same_operators_for_behavior_and_affect":True},out/"feature_schema.json")
    fold=out/f"fold_{cfg.fold:02d}"; save_json(split,fold/"split_indices.json")
    save_json({"dataset_sha256":dataset_id,"student_keys_in_dataset_order":[core.student_key(s["student_id"],dataset_id) for s in data.sequences],"split":split},fold/"split_identity_manifest.json")
    src=out/"source"; src.mkdir(exist_ok=True)
    for path in (Path(__file__),Path(core.__file__)):
        dest=src/path.name
        if not dest.exists(): shutil.copyfile(path,dest)
    print("Student partitions:",{k:len(v) for k,v in split.items()},flush=True)
    print("All heads have IDENTICAL cognitive and behavioral history. Affect features alone differ.",flush=True)
    for seed in cfg.seeds:
        seedout=fold/f"seed_{seed}"; sig=digest_obj({"root":signature,"seed":seed}); stage=seedout/"readouts"
        print(f"\n{'='*78}\nSEED {seed} — {'FINAL TEST' if cfg.evaluate_test else 'DEVELOPMENT VALIDATION'}\n{'='*78}",flush=True)
        complete=stage/"result.json"
        if complete.exists() and not cfg.evaluate_test:
            if json.loads(complete.read_text())["signature"]!=sig: raise RuntimeError("Completed seed signature mismatch.")
            if not cfg.resume: raise RuntimeError("Completed output exists; use a new directory.")
            print("Completed temporal readouts found; no retraining.",flush=True); comparative_reports(out,cfg); continue
        model,kt=obtain_encoder(data,split,cfg,device,seed,seedout/"dkt",sig,dataset_id)
        model.eval()
        for parameter in model.parameters(): parameter.requires_grad_(False)
        before=core.tensor_hash(model); encoder_sha=file_sha(seedout/"dkt/best.pt")
        cache=Path(cfg.local_dir)/"states"/f"seed_{seed}"; normalizer_path=stage/"normalizer.json"
        if cfg.evaluate_test:
            if not complete.exists() or not normalizer_path.exists(): raise RuntimeError("Finish all locked training before test evaluation.")
            result=json.loads(complete.read_text())
            if result["signature"]!=sig: raise RuntimeError("Test result signature mismatch.")
            normalizer=json.loads(normalizer_path.read_text())
            path=build_bank(model,data,split["test_indices"],cfg,device,cache,dataset_id,encoder_sha,"test")
            store=BankStore(path,normalizer,device,cfg.gpu_readout_budget_gib,cfg.split_seed+33003)
            heads=ReadoutBank(data.K,layout_for(cfg.hidden_dim)["dim"],cfg,[.5]*len(cfg.tasks)).to(device)
            policies={}
            for m,(task,profile) in enumerate(heads.members):
                ck=core.checked_checkpoint(stage/profile/f"best_{task}.pt",sig,encoder_sha); heads.load_member(m,ck["model"])
                report=json.loads((stage/profile/"validation_result.json").read_text()); policies[profile]=report["readiness_threshold_selection"]
            metric,prob=eval_readouts(heads,store,cfg)
            rows=export_readouts(heads,store,prob,metric,cfg,stage,sig,seed,data,dataset_id,result["best_epochs"],"test",policies)
            test_kt=core.eval_dkt(model,data,split["test_indices"],cfg,device,seedout/"dkt/test_predictions.npz",dataset_id)
            save_json({"signature":sig,"correctness":test_kt,"readouts":rows,"no_parameters_or_normalization_fitted":True,
                "fixed_capacity_policy_uses_scores_not_labels":True},seedout/"test_evaluation.json")
            del heads,store
        else:
            save_json(core.correctness_baselines(data,split,kt["validation"]),seedout/"dkt/baselines_validation.json")
            train_path=build_bank(model,data,split["train_indices"],cfg,device,cache,dataset_id,encoder_sha,"train")
            val_path=build_bank(model,data,split["validation_indices"],cfg,device,cache,dataset_id,encoder_sha,"validation")
            norm=fit_normalizer(train_path,layout_for(cfg.hidden_dim))
            if normalizer_path.exists() and json.loads(normalizer_path.read_text())!=core.clean_json(norm):
                raise RuntimeError("Saved normalizer differs from deterministic train-only fit.")
            save_json(norm,normalizer_path)
            save_json(training_feature_audit(norm,cfg),stage/"training_feature_audit.json")
            ts=BankStore(train_path,norm,device,cfg.gpu_readout_budget_gib,cfg.split_seed+33001)
            vs=BankStore(val_path,norm,device,cfg.gpu_readout_budget_gib,cfg.split_seed+33002)
            heads,result=train_readouts(ts,vs,cfg,device,seed,stage,sig,norm,data,dataset_id,encoder_sha)
            if core.tensor_hash(model)!=before: raise AssertionError("Frozen cognitive encoder changed.")
            save_json({"identical":True,"encoder_hash_before":before,"encoder_hash_after":core.tensor_hash(model),
                "correctness_shared_across_profiles":True},seedout/"frozen_backbone_check.json")
            save_json({"primary_question":make_research_protocol(cfg)["question"],"feature_prefix_audit":preflight["temporal_prefix_audit"],
                "same_temporal_behavior_for_every_profile":True,"validation_only":True,"new_affect_benefit_established":False,
                "note":"Interpret exported contrasts; passing integration tests does not establish educational predictive value."},seedout/"run_quality_report.json")
            del heads,ts,vs
        del model; gc.collect()
        if device.type=="cuda": torch.cuda.empty_cache()
        if not cfg.keep_local_states and cache.exists(): shutil.rmtree(cache)
        comparative_reports(out,cfg,"test" if cfg.evaluate_test else "validation")
    print("\nStored:",out,flush=True)
    print("HELD-OUT TEST WAS NOT EVALUATED." if not cfg.evaluate_test else "Explicit final evaluation completed without parameter fitting.",flush=True)
    return out


def _test_config(**kwargs):
    settings=dict(hidden_dim=8,readout_hidden=8,skill_embedding=2,device="cpu",require_a100=False,
        precision="fp32",run_tests=False,dkt_epochs=2,dkt_patience=2,dkt_batch=8,dkt_output_dropout=.2,
        readout_epochs=2,readout_patience=2,readout_batch=64,gpu_readout_budget_gib=0.,
        folds=4,policy_min_selected=1,bootstrap_replicates=100,affect_diagnostic_rows=64,prefix_audit_students=4,
        accept_assistments_terms=True,trust_own_cache=True,allow_download=False,encoder_source_root="")
    settings.update(kwargs); return Config(**settings)


def _write_test_bank(folder,x,y,skills=None,students=None,positions=None,tasks=("readiness",)):
    folder=Path(folder); folder.mkdir(parents=True,exist_ok=True); N=len(x)
    y=np.asarray(y,np.float32).reshape(N,len(tasks))
    arrays={"x":np.asarray(x,np.float32),"y":y,"mask":np.ones(y.shape,bool),
        "skill":np.ones(N,np.int64) if skills is None else np.asarray(skills,np.int64),
        "student_index":np.arange(N,dtype=np.int32) if students is None else np.asarray(students,np.int32),
        "event_position":np.zeros(N,np.int32) if positions is None else np.asarray(positions,np.int32),
        "exercise_id":np.ones(N,np.int32),"event_key":np.asarray([f"test_event_{j}" for j in range(N)],dtype="U24")}
    for k,a in arrays.items(): np.save(folder/f"{k}.npy",a)
    return folder


def _temporal_signal_fixture(cfg, pairs=160, seed=611):
    """Opposite histories, SAME snapshot/behavior/state within every paired example."""
    rng=np.random.default_rng(seed); D=layout_for(cfg.hidden_dim)["dim"]; L=layout_for(cfg.hidden_dim)
    xs=[]; ys=[]
    for j in range(pairs):
        state=rng.normal(0,.2,cfg.hidden_dim).astype(np.float32)
        background=rng.uniform(.15,.85,size=(3,4)).astype(np.float32)
        for rising in (False,True):
            affect=background.copy(); affect[:,0]=[.1,.3,.5] if rising else [.9,.7,.5]
            seq={"skill_ids":np.ones(3,int),"answers":np.ones(3,np.float32),"delta_ts":np.array([0,1,1],np.float32),
                "behavior_features":np.zeros((3,5),np.float32),"behavior_mask":np.ones((3,5),bool),
                "affect_values":affect,"affect_mask":np.ones((3,4),bool)}
            x=np.zeros((3,D),np.float32); x[:,:cfg.hidden_dim]=state
            for k,v in context_features(seq,cfg).items(): x[:,slice(*L[k])]=v
            xs.append(x[-1]); ys.append(float(rising))
    return np.asarray(xs),np.asarray(ys)


def run_temporal_tests():
    import unittest
    from unittest import mock
    module=sys.modules[__name__]
    class TemporalTests(unittest.TestCase):
        def setUp(self):
            core.seed_all(410); self.cfg=_test_config(tasks=("readiness",))
            self.seq=core.synthetic_payload(students=1)["sequences"][0]
            self.seq["behavior_mask"]=torch.ones_like(self.seq["behavior_features"],dtype=torch.bool)
            self.layout=layout_for(self.cfg.hidden_dim)
        def batch(self,n=12):
            D=self.layout["dim"]; x=torch.randn(n,D)
            for k in ("affect_mask","behavior_mask"): x[:,slice(*self.layout[k])]=1
            return {"x":x,"skill":torch.ones(n,dtype=torch.long),
                "donor_affect":x.flip(0)[:,slice(*self.layout["affect"])],
                "donor_mask":torch.ones(n,self.layout["affect"][1]-self.layout["affect"][0])}
        def test_01_hand_calculated_summary(self):
            v=np.array([[.1],[.2],[.5],[.8]])
            x,m=causal_summaries(v,np.ones_like(v,bool),np.array([1,2,1,1]),2,3)
            self.assertAlmostEqual(x[2,STATS.index("delta_previous")],.3,places=6)
            self.assertAlmostEqual(x[2,STATS.index("mean_short")],.35,places=6)
            self.assertAlmostEqual(x[2,STATS.index("mean_long")],.8/3,places=6)
            self.assertAlmostEqual(x[2,STATS.index("prior_student_mean")],.15,places=6)
            self.assertAlmostEqual(x[2,STATS.index("previous_same_skill")],.1,places=6)
            self.assertFalse(m[0,STATS.index("delta_previous")])
        def test_02_prefix_invariance(self):
            cfg=self.cfg; full=context_features(self.seq,cfg)
            for n in (1,3,9):
                prefix={k:v[:n] if torch.is_tensor(v) else v for k,v in self.seq.items()}
                part=context_features(prefix,cfg)
                for k in part: np.testing.assert_allclose(full[k][:n],part[k],atol=1e-6,rtol=0)
        def test_03_future_perturbation_does_not_change_earlier_features(self):
            old=context_features(self.seq,self.cfg); seq=copy.deepcopy(self.seq)
            seq["affect_values"][10:]=.97; seq["behavior_features"][10:]=200
            seq["answers"][10:]=1-seq["answers"][10:]; seq["skill_ids"][10:]=3
            new=context_features(seq,self.cfg)
            for k in old: np.testing.assert_allclose(old[k][:10],new[k][:10],atol=1e-6,rtol=0)
        def test_04_future_target_masks_never_enter_features(self):
            old=context_features(self.seq,self.cfg); seq=copy.deepcopy(self.seq)
            for t in core.TASKS:
                seq[t+"_targets"][:]=1-seq[t+"_targets"]
                seq[t+"_mask"][:]=~seq[t+"_mask"]
            new=context_features(seq,self.cfg)
            for k in old: np.testing.assert_array_equal(old[k],new[k])
        def test_05_missing_values_not_zero_observations(self):
            v=np.array([[.1],[np.nan],[.7]]); m=np.array([[1],[0],[1]],bool)
            x,mask=causal_summaries(v,m,np.ones(3,int),2,3)
            self.assertAlmostEqual(x[2,STATS.index("mean_long")],.4,places=6)
            self.assertAlmostEqual(x[2,STATS.index("delta_previous")],.6,places=6)
            self.assertAlmostEqual(x[2,STATS.index("coverage_long")],2/3,places=6)
            self.assertFalse(mask[1,STATS.index("current")]); self.assertTrue(np.isfinite(x).all())
        def test_06_same_skill_previous_skips_missing(self):
            v=np.array([[.1],[.2],[np.nan],[.8]]); m=np.isfinite(v)
            x,_=causal_summaries(v,m,np.array([1,2,1,1]),2,3)
            self.assertAlmostEqual(x[3,STATS.index("previous_same_skill")],.1,places=6)
            self.assertAlmostEqual(x[3,STATS.index("log1p_gap_same_skill")],math.log1p(3),places=6)
        def test_07_behavior_and_affect_same_operators(self):
            seq=copy.deepcopy(self.seq); seq["behavior_features"][:,:4]=seq["affect_values"]
            seq["behavior_mask"][:,:4]=seq["affect_mask"]
            f=context_features(seq,self.cfg); S=len(STATS)
            np.testing.assert_array_equal(f["behavior"][:,S:5*S],f["affect"])
            np.testing.assert_array_equal(f["behavior_mask"][:,S:5*S],f["affect_mask"])
        def test_08_student_state_is_reset(self):
            a=context_features(self.seq,self.cfg)
            other=copy.deepcopy(self.seq); other["affect_values"][:]=.999
            context_features(other,self.cfg)
            b=context_features(self.seq,self.cfg)
            np.testing.assert_array_equal(a["affect"],b["affect"])
            self.assertFalse(a["affect_mask"][0,STATS.index("prior_student_mean")])
        def test_09_lagged_mode_shifts_every_affect_stat(self):
            cfg=copy.deepcopy(self.cfg); cfg.affect_timing="lagged"
            old=context_features(self.seq,cfg); seq=copy.deepcopy(self.seq); seq["affect_values"][7]=.99
            new=context_features(seq,cfg)
            np.testing.assert_array_equal(old["affect"][:8],new["affect"][:8])
            self.assertFalse(old["affect_mask"][0,0]); self.assertTrue(np.any(old["affect"][8]!=new["affect"][8]))
        def test_09b_lagged_skill_scores_keep_original_skill(self):
            v=np.array([[.1],[.9],[.4],[.7],[.6]])
            x,m=lagged_affect_summaries(v,np.ones_like(v,bool),np.array([1,2,1,2,1]),2,3)
            self.assertAlmostEqual(x[2,STATS.index("current")],.9,places=6)
            self.assertAlmostEqual(x[2,STATS.index("previous_same_skill")],.1,places=6)
            self.assertFalse(m[2,STATS.index("delta_same_skill")])
            self.assertAlmostEqual(x[4,STATS.index("previous_same_skill")],.4,places=6)
            self.assertAlmostEqual(x[4,STATS.index("delta_same_skill")],.3,places=6)
            self.assertAlmostEqual(x[4,STATS.index("log1p_gap_same_skill")],math.log1p(2),places=6)
        def test_10_donor_identity_and_fixed_seed(self):
            skills=np.tile([1,2,1,2],12); students=np.repeat(np.arange(12),4); pos=np.tile(np.arange(4),12)
            d,a=donor_map(skills,students,pos,77); e,b=donor_map(skills,students,pos,77)
            np.testing.assert_array_equal(d,e); np.testing.assert_array_equal(skills[d],skills)
            self.assertTrue(np.all(students[d]!=students)); self.assertTrue(a["outcome_blind"])
        def test_11_donor_single_student_reported(self):
            d,a=donor_map(np.ones(8),np.ones(8),np.arange(8),1)
            np.testing.assert_array_equal(d,np.arange(8)); self.assertEqual(a["no_cross_student_donor_unchanged"],8)
        def test_12_no_affect_and_snapshot_are_isolated(self):
            model=ReadoutBank(4,self.layout["dim"],self.cfg,[.5]); b=self.batch()
