            result=model(b).detach()
            torch.testing.assert_close(expected[0],result[0],rtol=0,atol=0)
            torch.testing.assert_close(expected[1],result[1],rtol=0,atol=0)
            self.assertFalse(torch.equal(expected[2],result[2]))
