                actual=store.get(np.arange(40)); av=slice(*self.layout["affect"]); am=slice(*self.layout["affect_mask"])
                donor=x[store.perm]; expected=(donor[:,av]-np.asarray(norm["mean"])[av])/np.asarray(norm["std"])[av]
                np.testing.assert_allclose(actual["donor_affect"].numpy(),expected,rtol=1e-5,atol=1e-6)
