        def test_20_quota_selection_is_label_blind_and_tie_safe(self):
            p=np.array([.9,.9,.7,.6,.5,.4,.3,.2,.1,0]); y=np.array([1,0]*5)
            a=fixed_capacity_policy(y,p,.3,1); b=fixed_capacity_policy(1-y,p,.3,1)
            self.assertEqual(a["selected"],3); self.assertEqual(a["threshold"],b["threshold"])
            self.assertFalse(a["selection_uses_labels"])
            self.assertFalse(fixed_capacity_policy(y,np.ones(10),.3,1)["available"])
        def test_21_known_temporal_signal_not_available_in_snapshot(self):
            cfg=copy.deepcopy(self.cfg); cfg.readout_hidden=16
            x,y=_temporal_signal_fixture(cfg,160,713); xv,yv=_temporal_signal_fixture(cfg,80,992)
            with tempfile.TemporaryDirectory() as td:
                tr=_write_test_bank(Path(td)/"train",x,y); va=_write_test_bank(Path(td)/"validation",xv,yv)
                norm=fit_normalizer(tr,self.layout); ts=BankStore(tr,norm,torch.device("cpu"),0,812); vs=BankStore(va,norm,torch.device("cpu"),0,993)
                core.seed_all(551); model=ReadoutBank(4,self.layout["dim"],cfg,[.5]); opt=IndependentAdam(model.parameters(),lr=.012)
                batch=ts.get(np.arange(ts.N)); labels=torch.tensor(y).expand(4,-1)
                for _ in range(100):
                    opt.zero_grad(); loss=F.binary_cross_entropy_with_logits(model(batch),labels,reduction="none").mean(1).sum()
                    loss.backward(); core.clip_members(model); opt.step()
                model.eval()
                with torch.no_grad(): p=model(vs.get(np.arange(vs.N))).sigmoid().numpy()
                scores={profile:core.binary_metrics(yv,p[m])["auc"] for m,profile in enumerate(DEFAULT_PROFILES)}
                print("TEMPORAL SYNTHETIC POSITIVE CONTROL ONLY:",scores,flush=True)
                self.assertGreater(scores["temporal_affect"],.95)
                self.assertAlmostEqual(scores["temporal_behavior"],.5,places=6)
                self.assertAlmostEqual(scores["snapshot_affect"],.5,places=6)
                self.assertLess(scores["disrupted_affect"],.65)
        def test_22_null_fixture_cannot_manufacture_a_positive_effect(self):
            x,y=_temporal_signal_fixture(self.cfg,40,14)
            # For EVERY exact input, supply one positive and one negative label.
            repeated=np.repeat(x,2,axis=0); labels=np.tile([0.,1.],len(x))
            model=ReadoutBank(4,self.layout["dim"],self.cfg,[.5]); b={"x":torch.tensor(repeated),"skill":torch.ones(len(repeated),dtype=torch.long)}
